+export interface OutboundMappingField {
+  label: string;
+  value: string;
+  /**
+   * These widgets look alike but accept input differently, so the kind has to be declared per field.
+   *
+   * text   — plain rjsf string input; filled directly.
+   * pick   — readonly autocomplete (`Mui-readOnly`, e.g. 'Asset'); cannot be typed into, so it is
+   *          opened by clicking and the value is chosen from the listbox.
+   * search — editable autocomplete (e.g. 'Attribute'); typed into to filter, then chosen.
+   * commit — editable autocomplete whose listbox renders the match as a disabled button, so the
+   *          option is not clickable and the typed value is committed with Enter.
+   */
+  kind: 'text' | 'pick' | 'search' | 'commit';
+}
+
 export const createDatabricksOutboundSyncConfigurationComponent = (page: Page) => {
   const parentContainer = page.getByRole('tabpanel');

-  const tagMappingsContainer = parentContainer
-    .getByRole('heading', {
-      name: 'Tag Mappings',
-    })
-    .locator('../..');
-  const addTagMappingButton = parentContainer.getByRole('button', {
-    name: 'Add Tag Mapping',
-  });
-  const assetTypeCombobox = parentContainer.getByRole('combobox', { name: 'Asset' });
-  const attributeCombobox = parentContainer.getByRole('combobox');
-  const tagKeyInput = parentContainer.getByRole('textbox');
-  const attributeFieldFirstInput = createCombobox(tagMappingsContainer, 'Select');
-  const attributeFieldSecondInput = createCombobox(tagMappingsContainer, 'Select', true, 1);
+  // TODO: Try to improve. No accessible locator available — rjsf wraps each mapping section in an
+  // unlabelled <div>, so the section is reached by traversing up from its heading. The heading is
+  // matched exactly because seven of the eight sections share the "to Databricks tag mappings" suffix.
+  const outboundMappingSection = (heading: string) =>
+    parentContainer.getByRole('heading', { name: heading, exact: true }).locator('../..');
+  const addOutboundMappingButton = (heading: string) =>
+    outboundMappingSection(heading).getByRole('button', { name: /^Add/ });
+
+  const addOutboundMapping = async (heading: string, fields: OutboundMappingField[]): Promise<void> => {
+    const section = outboundMappingSection(heading);
+    const rows = section.getByRole('button', { name: /^Remove/ });
+    const rowCountBeforeAdd = await rows.count();
+
+    await addOutboundMappingButton(heading).click();
+    await rows.nth(rowCountBeforeAdd).waitFor({ state: 'visible' });
+
+    for (const { label, value, kind } of fields) {
+      if (kind === 'text') {
+        await section.getByRole('textbox', { name: label, exact: true }).last().fill(value);
+      } else {
+        const combobox = section.getByRole('combobox', { name: label, exact: true }).last();
+
+        if (kind === 'pick') {
+          await combobox.click();
+        } else {
+          await combobox.fill(value);
+        }
+
+        if (kind === 'commit') {
+          await combobox.press('Enter');
+        } else {
+          await page.getByRole('option', { name: value, exact: true }).first().click();
+        }
+      }
+    }
+  };

   return {
-    tagMappingsContainer,
-    addTagMappingButton,
-    assetTypeCombobox,
-    attributeCombobox,
-    tagKeyInput,
-    attributeFieldFirstInput,
-    attributeFieldSecondInput,
+    parentContainer,
+    outboundMappingHeadings: DATABRICKS_OUTBOUND_MAPPING_HEADINGS,
+    outboundMappingSection,
+    addOutboundMappingButton,
+    addOutboundMapping,
   };
 };

